pseudocode:
1. npm install @notionhq/client
2. lib/notion.ts:
   import { Client } from '@notionhq/client'
   import type { Project } from '@/types/project'

   const notion = new Client({ auth: process.env.NOTION_API_KEY })
   let cachedDataSourceId: string | null = null

   async function resolveDataSourceId(): Promise<string> {
     if (cachedDataSourceId) return cachedDataSourceId
     const db = await notion.databases.retrieve({ database_id: process.env.NOTION_DATABASE_ID! })
     cachedDataSourceId = db.data_sources[0].id
     return cachedDataSourceId
   }

   function parseProject(page): Project {
     const props = page.properties
     // title: props['제목'].title[].plain_text 합치기
     // description: props['설명'].rich_text[].plain_text 합치기
     // thumbnailUrl: props['썸네일'].files[0]?.type === 'external' ? .external.url : .file.url, 없으면 null
     // tags: props['태그'].multi_select.map(o => o.name)
     // link: props['링크'].url
     // isPublished: props['공개여부'].checkbox
     // order: props['정렬순서'].number
     return { id: page.id, title, description, thumbnailUrl, tags, link, isPublished, order }
   }

   export async function getPublishedProjects(): Promise<Project[]> {
     const dataSourceId = await resolveDataSourceId()
     const response = await notion.dataSources.query({
       data_source_id: dataSourceId,
       filter: { property: '공개여부', checkbox: { equals: true } },
       sorts: [{ property: '정렬순서', direction: 'ascending' }],
     })
     return response.results.map(parseProject)
   }

